def incremental_ema(window, alpha=0.1, last_ema=None):
    if last_ema is None:
        last_ema = window[0]
    else:
        last_ema = alpha * window[-1] + (1 - alpha) * last_ema
    return last_ema, last_ema

# Find peaks in the signal array
