To allow administrators to choose which photo to keep when duplicates are submitted, we'll modify the backend to handle duplicate submissions by temporarily storing them and providing an endpoint for administrators to resolve duplicates. Additionally, we will update the frontend to provide user feedback when an upload is rejected due to a duplicate entry.

### Backend Implementation

We'll modify the backend to handle duplicate submissions by storing them temporarily and notifying the administrator.

#### Code Changes

1. **Add a Pending Photos Table**: We add a `pending_photos` table to store duplicate submissions temporarily.

```python
import sqlite3
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import os

app = Flask(__name__)

def init_db():
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS photos
                 (id INTEGER PRIMARY KEY, name TEXT, price REAL, description TEXT, filename TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS pending_photos
                 (id INTEGER PRIMARY KEY, name TEXT, price REAL, description TEXT, filename TEXT)''')
    conn.commit()
    conn.close()

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return "No file part", 400
    file = request.files['file']
    if file.filename == '':
        return "No selected file", 400
    if file:
        filename = secure_filename(file.filename)
        file.save(os.path.join("uploads/", filename))

        # Extract other form data
        name = request.form.get('name')
        price = float(request.form.get('price'))
        description = request.form.get('description')

        # Check for duplicate names
        conn = sqlite3.connect('photos.db')
        c = conn.cursor()
        c.execute("SELECT * FROM photos WHERE name=?", (name,))
        existing_photo = c.fetchone()

        if existing_photo:
            # Store duplicate photo in pending table
            c.execute("INSERT INTO pending_photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (name, price, description, filename))
            conn.commit()
            conn.close()
            return f"Duplicate name {name}, please contact admin to resolve.", 409

        # Insert new photo details into database
        c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                  (name, price, description, filename))
        conn.commit()
        conn.close()

        return "File uploaded successfully", 200

@app.route('/admin/resolve_duplicate', methods=['POST'])
def resolve_duplicate():
    photo_id = request.form.get('id')
    action = request.form.get('action')  # 'keep' or 'delete'
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute("SELECT * FROM pending_photos WHERE id=?", (photo_id,))
    pending_photo = c.fetchone()

    if pending_photo:
        if action == 'keep':
            c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (pending_photo[1], pending_photo[2], pending_photo[3], pending_photo[4]))
            c.execute("DELETE FROM pending_photos WHERE id=?", (photo_id,))
        elif action == 'delete':
            c.execute("DELETE FROM pending_photos WHERE id=?", (photo_id,))
    conn.commit()
    conn.close()
    return "Resolved", 200

if __name__ == '__main__':
    init_db()
    app.run(debug=True)
```

### Explanation

- **Pending Photos Table**: We added a `pending_photos` table to store duplicate submissions temporarily.
- **Duplicate Handling**: When a duplicate submission is detected, it is stored in the `pending_photos` table and the user is notified to contact an administrator.
- **Resolve Duplicate Endpoint**: The `/admin/resolve_duplicate` endpoint allows administrators to either keep or delete the pending photo. If they choose to keep it, it is moved to the `photos` table, and the duplicate is removed from the `pending_photos` table.

